(()=>{
 const M=SACCR,{m,n,pct,slider,select,bars,add,green,amber}=SACCR_UI;
 add({id:'saccr-netting',name:'Netting versus hedging sets',stage:'01 · Exposure foundations',title:'Legal netting and risk offsets work at different levels',intro:'A netting set defines which contractual values can be combined. Hedging sets govern offsets in the future-exposure calculation within that legal boundary.',chart:'Current positive exposure with and without netting',inputs:[slider('a','Trade A value',-30,30,1,20),slider('b','Trade B value',-30,30,1,-15),select('net','Netting recognition',[['yes','Recognised single netting set'],['no','Separate transaction netting sets']],'yes')],challenge:'Offset the two values exactly. Does that establish that their future risks also offset?',formula:'Recognised netting: RC = max(VA + VB, 0)\nWithout netting: RC total = max(VA,0) + max(VB,0)',key:'This compares replacement cost with zero collateral. PFE additionally depends on risk categories, hedging sets and trade risk positions.',simple:'Two trades may offset in value today but react differently tomorrow. Legal netting lets you combine claims at close-out; regulatory hedging sets determine how much future-risk offset is recognised. Both layers matter.',scope:'Two trades, no collateral and no PFE in this first comparison. The recognised-netting choice assumes the legal and operational conditions are met, rather than establishing them.',rule:'Articles 274(1), 277 and 277a',notes:[['Recognised netting','The contractual arrangement must satisfy the requirements, including enforceability and the Article 297 obligations. If conditions fail, each transaction is treated as its own netting set.'],['Mapping material drivers','A transaction with material drivers in different risk categories is mapped to each relevant category. Inflation belongs to interest-rate risk; climatic conditions belong to commodity risk.']],compute(s){const gross=Math.max(s.a,0)+Math.max(s.b,0),net=Math.max(s.a+s.b,0),r=s.net==='yes'?net:gross;return {stats:[['Selected RC',m(r)],['Unnetted RC',m(gross)],['Current offset benefit',m(gross-r)]],bars:bars(['Trade A','Trade B','Unnetted RC','Selected RC'],[s.a,s.b,gross,r]),headers:['Calculation','Result'],rows:[['Sum of signed values',m(s.a+s.b)],['Sum of positive values',m(gross)],['Positive part after recognised netting',m(net)]],explanation:'Selected replacement cost is '+m(r)+'. '+(s.net==='yes'?'The payable can offset the receivable before the positive part is taken.':'The payable cannot offset the receivable across these separate sets.')+' A separate PFE calculation is still needed.',note:'A shared counterparty alone does not establish a recognised netting set.'};}});
 add({id:'saccr-rc',name:'Replacement cost',stage:'01 · Exposure foundations',title:'Which amount remains unsecured today?',intro:'Replacement cost is floored at zero. For margined sets, it also reflects the threshold and minimum transfer amount in the agreement.',chart:'The competing replacement-cost terms',inputs:[select('margin','Margin treatment',[['no','Unmargined'],['yes','Margined · eligible to receive VM']],'yes'),slider('v','Current market value (CMV)',-20,40,1,12),slider('vm','Variation margin received / posted',-20,40,1,10),slider('nica','Net independent collateral',-10,20,1,2),slider('th','Threshold',0,10,.5,3),slider('mta','Minimum transfer amount',0,5,.5,1)],challenge:'Cover the current market value with variation margin. Can the agreement terms still leave positive RC?',formula:'Unmargined: RC = max(CMV − NICA, 0)\nMargined: RC = max(CMV − VM − NICA, TH + MTA − NICA, 0)',key:'Received collateral is positive; posted collateral is negative. Inputs are already eligible and volatility-adjusted. VM, TH and MTA are unused in unmargined mode.',simple:'The first term asks what is not covered now. The threshold term asks how much exposure can remain before the margin process requires another transfer. The larger term determines replacement cost.',scope:'One netting set and one margin agreement. A one-way agreement under which the firm posts but cannot receive VM follows the unmargined RC treatment, with VM included in NICA; that conversion is not automatic in these inputs.',rule:'Articles 275–276',compute(s){const yes=s.margin==='yes',gap=s.v-(yes?s.vm:0)-s.nica,threshold=yes?s.th+s.mta-s.nica:0,r=M.rc(s.v,s.vm,s.nica,s.th,s.mta,yes);return {stats:[['Replacement cost',m(r)],['Current unsecured term',m(gap)],['Agreement term',yes?m(threshold):'Not applicable']],bars:bars(['Current gap','Agreement term','Zero floor','RC'],[gap,threshold,0,r]),headers:['Term','Amount','Treatment'],rows:[['CMV less applicable collateral',m(gap),'Can be negative'],['TH + MTA − NICA',yes?m(threshold):'Not used','Margined treatment only'],['Zero floor',m(0),'No negative RC'],['Maximum',m(r),'Replacement cost']],explanation:'Replacement cost is '+m(r)+'. '+(yes&&threshold>Math.max(gap,0)?'The agreement term is binding, even though the current unsecured amount is smaller.':gap>0?'The current unsecured exposure is the binding term.':'The zero floor or agreement term prevents negative replacement cost.'),note:'Do not count the same collateral in both variation margin and NICA.'};}});
 add({id:'saccr-collateral',name:'Collateral signs and haircuts',stage:'01 · Exposure foundations',title:'Collateral’s recognised value can differ from its face value',intro:'Volatility adjustments account for changes in collateral value and currency mismatch. Posted collateral has the opposite exposure effect to received collateral.',chart:'Face value and exposure adjustment',inputs:[slider('c','Collateral face amount',0,40,1,10),slider('hc','Collateral haircut input',0,30,1,5,'%'),slider('hfx','Currency mismatch haircut input',0,20,1,8,'%'),select('direction','Collateral direction',[['received','Received'],['posted','Posted · not bankruptcy remote'],['segregated','Posted independent collateral · bankruptcy remote']],'received')],challenge:'Keep the collateral amount fixed and switch from received to posted. Why does the sign change?',formula:'Received: recognised C = C × (1 − HC − HFX)\nPosted: recognised C = −C × (1 + HC + HFX)\nBankruptcy-remote posted independent collateral is excluded from NICA',key:'Haircut sliders are illustrative inputs, not a PRA lookup table. Actual haircuts require eligible collateral, the prescribed method and the applicable liquidation period.',simple:'Received collateral is a resource available against a claim. Posted collateral that is exposed to the counterparty’s bankruptcy can itself become an amount at risk. Haircuts reduce the credit for assets received and increase the exposure associated with assets posted.',scope:'A single eligible collateral item, with no other adjustments. The bankruptcy-remote choice concerns independent collateral and the NICA exclusion in Article 276(1)(g), not every posted margin arrangement.',rule:'Article 276 and its Article 223 cross-reference',compute(s){const h=(s.hc+s.hfx)/100,r=s.direction==='received'?s.c*(1-h):s.direction==='posted'?-s.c*(1+h):0;return {stats:[['Signed recognised amount',m(r)],['Combined haircut',pct(h)],['Collateral direction',s.direction]],bars:bars(['Face amount','Recognised amount'],[s.c,r]),headers:['Step','Result'],rows:[['Face amount',m(s.c)],['HC + HFX',pct(h)],['Signed collateral contribution',m(r)]],explanation:'The signed collateral contribution is '+m(r)+'. '+(r>0?'It can reduce the unsecured term.':r<0?'Subtracting this negative collateral increases the unsecured term.':'The selected bankruptcy-remote independent collateral is excluded from NICA.'),note:'Recognise each item once. Collateral eligibility and enforceability come before haircut arithmetic.'};}});
 add({id:'saccr-pfe',name:'PFE and its multiplier',stage:'02 · Future exposure building blocks',title:'Excess collateral lowers PFE, but leaves a floor',intro:'The aggregate add-on measures potential changes in value. The multiplier adjusts it for negative net market value or excess collateral.',chart:'PFE as the unsecured amount changes',inputs:[slider('z','CMV less applicable collateral',-100,50,1,-10),slider('addon','Aggregate add-on',0,40,1,10)],challenge:'Make the unsecured amount very negative. Why does PFE approach a positive floor when the add-on is non-zero?',formula:'PFE = multiplier × AggAddOn\nFor z ≥ 0: multiplier = 1\nFor z < 0: multiplier = 0.05 + 0.95 × exp[z / (1.9 × AggAddOn)]',key:'z = CMV − NICA for an unmargined set; z = CMV − VM − NICA for one margined set. Floor = 5%. Zero aggregate add-on gives zero PFE; the displayed multiplier then uses its limiting value.',simple:'Being owed nothing today is not proof that future exposure cannot arise. Excess collateral creates a cushion, but the framework retains a minimum fraction of the add-on for potential future changes.',scope:'One netting set, with its aggregate add-on supplied directly. A shared margin agreement across multiple legal netting sets follows the separate Article 278(2) treatment.',rule:'Article 278',compute(s){const u=M.mult(s.z,s.addon),p=u*s.addon;return {stats:[['PFE',m(p)],['Multiplier',pct(u)],['PFE floor',m(.05*s.addon)]],series:[{name:'PFE (£m)',color:green,data:Array.from({length:151},(_,i)=>[i-100,M.mult(i-100,s.addon)*s.addon])},{name:'5% add-on floor',color:amber,data:[[-100,.05*s.addon],[50,.05*s.addon]]}],xlabel:'CMV less applicable collateral (£m)',headers:['Component','Value'],rows:[['Unsecured amount z',m(s.z)],['Aggregate add-on',m(s.addon)],['Multiplier',pct(u)],['PFE',m(p)]],explanation:'The multiplier is '+pct(u)+', producing '+m(p)+' of future exposure. '+(s.z>=0?'A non-negative unsecured amount receives no multiplier reduction.':'The negative unsecured amount reduces PFE towards its 5% floor.'),note:'The multiplier does not reduce replacement cost; RC is calculated separately.'};}});
 add({id:'saccr-duration',name:'Adjusted notional and duration',stage:'02 · Future exposure building blocks',title:'The same notional can represent different rate exposure',intro:'Interest-rate and credit transactions use supervisory duration to adjust notional for the period during which contractual payments are exposed.',chart:'Adjusted notional across end dates',inputs:[slider('notional','Contract notional',0,200,5,100),slider('start','Start in',0,5,.25,0,'years'),slider('length','Time from start to end',.25,20,.25,5,'years')],challenge:'Hold the payment-period length fixed and move its start further into the future. What happens to supervisory duration?',formula:'SD = [exp(−0.05 S) − exp(−0.05 E)] / 0.05\nAdjusted notional = contractual notional × SD',key:'S is time to the start of fixing or payments; E is time to the last relevant payment. Already-started transactions use S = 0. The 5% is a supervisory discount parameter, not today’s market rate.',simple:'Notional tells you the scale of the contract, but a long stream of rate-sensitive payments has more scope to move than a short stream. Supervisory duration provides a standardised way to reflect that difference.',scope:'Constant notional and a simple payment period with E = S + the length control. No amortisation, optional termination, repeated notional exchanges or leveraged cash flows. FX and equity/commodity notionals follow different definitions.',rule:'Article 279b',compute(s){const e=s.start+s.length,d=M.sd(s.start,e),a=s.notional*d;return {stats:[['Supervisory duration',n(d)],['Adjusted notional',m(a)],['End date E',e+' years']],series:[{name:'Adjusted notional (£m)',color:green,data:Array.from({length:81},(_,i)=>[s.start+i*.25,s.notional*M.sd(s.start,s.start+i*.25)])}],xlabel:'End date E (years from today)',headers:['Component','Value'],rows:[['Contract notional',m(s.notional)],['S / E',s.start+' / '+e+' years'],['Supervisory duration',n(d)],['Adjusted notional',m(a)]],explanation:'The adjusted notional is '+m(a)+', using supervisory duration '+n(d)+'. This amount still needs supervisory delta and the maturity factor before it becomes a trade risk position.',note:'Supervisory duration and the maturity factor serve different purposes; neither is an option’s expiry by default.'};}});
 add({id:'saccr-delta',name:'Supervisory delta',stage:'02 · Future exposure building blocks',title:'Direction and optionality shape the risk position',intro:'Linear trades generally have supervisory delta +1 or −1. Options use a prescribed formula and supervisory volatility, rather than the desk’s own market delta.',chart:'Supervisory delta across underlying prices',inputs:[select('asset','Option underlying',[['fx','FX · supervisory volatility 15%'],['equity','Single equity · supervisory volatility 120%']],'fx'),select('kind','Option type',[['call','Call'],['put','Put']],'call'),select('side','Position',[['buy','Bought'],['sell','Sold']],'buy'),slider('price','Underlying price',20,200,5,100,'price units'),slider('strike','Strike',20,200,5,100,'price units'),slider('expiry','Option expiry',.25,5,.25,1,'years')],challenge:'Switch a bought call to a sold call, then a bought put. Separate the direction of the risk from the size of delta.',formula:'d = [ln(P/K) + ½σ²T] / (σ√T)\nBought call: δ = N(d); bought put: δ = −N(−d)\nSold positions reverse the sign\nTrade risk position = δ × adjusted notional × MF',key:'This positive-price example uses shift λ = 0. Supervisory volatilities are prescribed. Interest-rate options, negative prices and securitisation tranches need their specific treatments.',simple:'An option does not react like a full unit of its underlying in every state. Its delta changes with moneyness and time. The supervisory formula standardises that behaviour while retaining the sign of bought and sold exposure.',scope:'European-style FX or single-name equity options with positive price and strike, using spot as P. This is not an option-pricing or market-hedging calculator.',rule:'Articles 279–279a',reference:{headers:['Underlying','Supervisory volatility'],rows:[['FX','15%'],['Single-name / multi-name credit','100% / 80%'],['Single-name / multi-name equity','120% / 75%'],['Electricity / other commodity','150% / 70%'],['Interest rate / other risk','50% / 150%']]},compute(s){const v=s.asset==='fx'?.15:1.2,f=p=>M.delta(p,s.strike,s.expiry,v,s.kind,s.side==='buy'),d=f(s.price);return {stats:[['Supervisory delta',n(d)],['Supervisory volatility',pct(v)],['Direction',d>=0?'Long driver':'Short driver']],series:[{name:'Supervisory delta',color:green,data:Array.from({length:91},(_,i)=>[20+i*2,f(20+i*2)])}],y:[-1,1],xlabel:'Underlying price',headers:['Input / result','Value'],rows:[['P / K',s.price+' / '+s.strike],['Expiry',s.expiry+' years'],['Prescribed volatility',pct(v)],['Delta',n(d)]],explanation:'Supervisory delta is '+n(d)+'. The sign tells you whether this position benefits from the selected risk driver rising, while its magnitude scales adjusted notional before aggregation.',note:'A sold option is not automatically zero EAD. The sold-options-only exception has additional conditions in Article 274(5).'};}});
 add({id:'saccr-maturity',name:'Maturity and margin period',stage:'02 · Future exposure building blocks',title:'Future exposure depends on the time available for markets to move',intro:'Unmargined trades use remaining maturity with a floor and cap. Margined trades use the margin period of risk (MPOR).',chart:'Unmargined and margined maturity factors',inputs:[slider('years','Remaining contractual maturity',.01,5,.01,2,'years'),slider('mpor','Assumed valid MPOR',10,60,1,10,'business days')],challenge:'Increase remaining maturity beyond one year. Then lengthen MPOR while keeping trade maturity unchanged.',formula:'Unmargined MF = √min[max(M, 10 / 250), 1]\nMargined MF = 1.5 × √(MPOR / 250)',key:'250 business days per year is the example convention. The ten-business-day floor applies to unmargined M. MPOR must be determined under the referenced rules, not selected to minimise exposure.',simple:'Without margin, the position can build exposure over its remaining life. With margin, the relevant gap is the period after the last effective exchange until risk can be closed out. Slower close-out increases this allowance.',scope:'The MPOR control assumes a valid bilateral derivative MPOR of at least 10 business days. It does not determine regulatory eligibility or operational extensions. Article 279c specifies a five-day minimum substitution for qualifying client/clearing-member transactions; other MPOR conditions and extensions still apply.',rule:'Article 279c, referring to Article 285(2)–(5)',compute(s){const u=M.mf(s.years,0,false),v=M.mf(0,s.mpor,true);return {stats:[['Unmargined MF',n(u)],['Margined MF',n(v)],['Selected MPOR',s.mpor+' days']],series:[{name:'Unmargined MF',color:green,data:Array.from({length:101},(_,i)=>[i/20,M.mf(i/20,0,false)])},{name:'Selected margined MF',color:amber,data:[[0,v],[5,v]]}],xlabel:'Remaining maturity (years)',headers:['Treatment','Horizon','Maturity factor'],rows:[['Unmargined',s.years+' years',n(u)],['Margined',s.mpor+' business days',n(v)]],explanation:'The unmargined factor is '+n(u)+' and the selected margined factor is '+n(v)+'. The unmargined factor stops rising at a one-year horizon; the margined calculation responds to MPOR instead.',note:'Margin frequency, disputes and difficult close-out can affect the required MPOR. This applet takes MPOR as an input.'};}});
})();

